const dec = o => o.lines.forEach(l => { const q = db.products.find(x => x.id === l.id); if (q) q.stock = Math.max(0, q.stock - l.q); });
const restock = o => o.lines.forEach(l => { const q = db.products.find(x => x.id === l.id); if (q) q.stock += l.q; });
