const UP_MIME = { ".jpg": "image/jpeg", ".png": "image/png", ".webp": "image/webp" };
function serveUpload(req, res, p) {
  const n = p.slice(9);
  if (!/^[a-f0-9]{16}\.(jpg|png|webp)$/.test(n)) throw fail(404, "Bulunamadı");
  fs.readFile(path.join(UPLOAD_DIR, n), (err, buf) => {
    if (err) { res.writeHead(404, { "Content-Type": "text/plain; charset=utf-8" }); return res.end("Görsel bulunamadı"); }
    res.writeHead(200, { "Content-Type": UP_MIME[path.extname(n)], "Content-Length": buf.length, "Cache-Control": "public, max-age=31536000, immutable" });
    res.end(req.method === "HEAD" ? undefined : buf);
  });
}
const MIME = { ".html": "text/html; charset=utf-8", ".css": "text/css; charset=utf-8", ".js": "text/javascript; charset=utf-8", ".png": "image/png", ".jpg": "image/jpeg", ".svg": "image/svg+xml", ".ico": "image/x-icon", ".txt": "text/plain; charset=utf-8", ".xlsx": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" };
function indexHtml() { try { return fs.readFileSync(path.join(ROOT, "index.html"), "utf8"); } catch (e) { return ""; } }
function indexHtml() { const f = FILES["/index.html"]; return f ? f[1].toString("utf8") : ""; }
const FILES = Object.fromEntries(Object.entries(EMBED).map(([k, v]) => [k, [v[0], Buffer.from(v[1], "base64")]]));
function serve(req, res, p) {
  if (req.method !== "GET" && req.method !== "HEAD") throw fail(405, "İzin yok");
  if (p === "/") p = "/index.html"; else if (p === "/admin") p = "/admin.html";
  const f = FILES[p];
  if (!f) { res.writeHead(404, { "Content-Type": "text/plain; charset=utf-8" }); return res.end("Sayfa bulunamadı"); }
  res.writeHead(200, { "Content-Type": MIME[f[0]] || "application/octet-stream", "Content-Length": f[1].length, "Cache-Control": /^\.(html|css|js)$/.test(f[0]) ? "no-cache" : "public, max-age=3600", ...(f[0] === ".xlsx" ? { "Content-Disposition": 'attachment; filename="urun-sablonu.xlsx"' } : {}) });
  res.end(req.method === "HEAD" ? undefined : f[1]);
}

http.createServer(async (req, res) => {
  res.setHeader("X-Content-Type-Options", "nosniff");
  res.setHeader("X-Frame-Options", "SAMEORIGIN");
  res.setHeader("Referrer-Policy", "same-origin");
  const p = (req.url || "/").split("?")[0];
  try {
    if (p === "/healthz") return send(res, 200, { ok: true });
    if (p.startsWith("/api/")) return await api(req, res, p);
    if (p === "/sozlesme") return contractPage(res);
    if (p === "/sitemap.xml") return sitemap(res);
    if (p === "/robots.txt") { res.writeHead(200, { "Content-Type": "text/plain; charset=utf-8" }); return res.end("User-agent: *\nAllow: /\nDisallow: /admin\nDisallow: /api/\nSitemap: " + SITE_URL + "/sitemap.xml\n"); }
    const pm = /^\/urun\/(\d+)(?:-[a-z0-9-]*)?\/?$/.exec(p); if (pm) return productPage(res, +pm[1]);
    if (p.startsWith("/uploads/")) return serveUpload(req, res, p);
    serve(req, res, p);
  } catch (e) {
    if (!e.code || typeof e.code !== "number") console.error(e);
    send(res, typeof e.code === "number" ? e.code : 500, { error: typeof e.code === "number" ? e.message : "Sunucu hatası" });
  }
}).listen(PORT, () => console.log("FrenServosu çalışıyor: http://localhost:" + PORT + (ADMIN ? "" : "  (uyarı: ADMIN_PASSWORD yok, yönetim paneli kapalı)")));
